+    /// When read from a zip file, this may not be a reasonable value
+    pub fn day(&self) -> u8 {
+        self.day
+    }
+
+    /// Get the hour
+    ///
+    /// # Warning
+    ///
+    /// When read from a zip file, this may not be a reasonable value
+    pub fn hour(&self) -> u8 {
+        self.hour
+    }
+
+    /// Get the minute
+    ///
+    /// # Warning
+    ///
+    /// When read from a zip file, this may not be a reasonable value
+    pub fn minute(&self) -> u8 {
+        self.minute
+    }
+
+    /// Get the second
+    ///
